#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define W 800
#define H 600

static float SCx=0.0f, SCy=-0.5f, SCz=-5.0f, SR=1.0f;
static float Lx, Ly, Lz;

typedef struct { float px,py,pz,t; float nx,ny,nz; int hit; } Hit;

static Hit sphere_intersect(float ox,float oy,float oz,float dx,float dy,float dz){
    Hit h; h.hit=0; h.px=h.py=h.pz=h.t=h.nx=h.ny=h.nz=0.0f;
    float ocx=ox-SCx, ocy=oy-SCy, ocz=oz-SCz;
    float a=(dx*dx+dy*dy)+dz*dz;
    float b=2.0f*((ocx*dx+ocy*dy)+ocz*dz);
    float c=(ocy*ocy+ocx*ocx+ocz*ocz)-SR*SR;
    float disc=b*b - c*(4.0f*a);
    if(disc<0.0f) return h;
    double sq=sqrt((double)disc);
    float twoa=a+a;
    float t=(float)(((double)(-b)-sq)/(double)twoa);
    if(!(t>=1e-3f)){
        t=(float)(((double)(-b)+sq)/(double)twoa);
        if(!(t>=1e-3f)) return h;
    }
    float px=dx*t+ox, py=dy*t+oy, pz=dz*t+oz;
    float nx=px-SCx, ny=py-SCy, nz=pz-SCz;
    float nl=sqrtf((nx*nx+ny*ny)+nz*nz);
    h.hit=1; h.t=t; h.px=px; h.py=py; h.pz=pz;
    h.nx=nx/nl; h.ny=ny/nl; h.nz=nz/nl;
    return h;
}

int main(void){
    fprintf(stderr,"Creating high-resolution image: %dx%d\n", W, H);
    fputs("This will be downsampled with ffmpeg after rendering\n", stderr);

    /* light = normalize(1,1,-1) */
    float L=sqrtf((1.0f*1.0f+1.0f*1.0f)+(-1.0f)*(-1.0f));
    Lx=1.0f/L; Ly=1.0f/L; Lz=-1.0f/L;

    float *img=(float*)malloc((size_t)W*H*3*sizeof(float));
    fputs("Rendering high-resolution image...\n", stderr);

    for(int y=0;y<H;y++){
        float p=100.0f*(float)y/600.0f;
        fprintf(stderr,"\rProgress: %.1f%%", (double)p);
        float v=(float)y/599.0f;
        float dy0=2.0f*(1.0f-v)-1.0f;
        for(int x=0;x<W;x++){
            float u=(float)x/799.0f;
            float dx=2.6666667f*u-1.3333334f;
            float dy=dy0;
            float dz=-1.0f;
            float len=sqrtf((dx*dx+dy*dy)+dz*dz);
            dx/=len; dy/=len; dz/=len;

            Hit hs=sphere_intersect(0.0f,0.0f,0.0f,dx,dy,dz);

            int planeHit=0; float tp=0.0f, ppx=0,ppy=0,ppz=0;
            if(fabsf(dy)>=1e-4f){
                tp=-1.5f/dy;
                if(tp>=1e-3f){ planeHit=1; ppx=dx*tp; ppy=dy*tp; ppz=dz*tp; }
            }

            int obj; /* 0 sky, 1 sphere, 2 plane */
            if(hs.hit && (!planeHit || tp>hs.t)) obj=1;
            else if(planeHit) obj=2;
            else obj=0;

            float R,G,B;
            if(obj==0){
                float t=(dy+1.0f)*0.5f; float omt=1.0f-t;
                R=t*0.5f+omt; G=t*0.7f+omt; B=t+omt;
            } else {
                float spx,spy,spz,nx,ny,nz;
                if(obj==1){ spx=hs.px;spy=hs.py;spz=hs.pz; nx=hs.nx;ny=hs.ny;nz=hs.nz; }
                else { spx=ppx;spy=ppy;spz=ppz; nx=0.0f;ny=1.0f;nz=0.0f; }
                Hit sh=sphere_intersect(spx,spy,spz,Lx,Ly,Lz);
                float lighting;
                if(sh.hit) lighting=0.2f;
                else {
                    float dot=(nx*Lx+ny*Ly)+nz*Lz;
                    float m=(float)fmax(0.0,(double)dot);
                    lighting=0.8f*m+0.2f;
                }
                if(obj==1){ R=lighting; G=0.2f*lighting; B=0.2f*lighting; }
                else {
                    float base = (((int)(floorf(spx)+floorf(spz)))&1) ? 0.4f : 0.9f;
                    float val=base*lighting; R=val; G=val; B=val;
                }
            }
            float *pix=img+((size_t)y*W+x)*3;
            pix[0]=R; pix[1]=G; pix[2]=B;
        }
    }
    fputs("\nRendering complete\n", stderr);

    FILE *f=fopen("image.ppm","w");
    fprintf(f,"P3\n%d %d\n255\n", W, H);
    for(size_t i=0;i<(size_t)W*H;i++){
        float *pix=img+i*3; int ch[3];
        for(int k=0;k<3;k++){
            double d=(double)pix[k]; d=fmax(d,0.0); d=fmin(d,1.0);
            ch[k]=(int)((float)d*255.99f);
        }
        fprintf(f,"%d %d %d\n", ch[0], ch[1], ch[2]);
    }
    fclose(f);
    fprintf(stderr,"Wrote image to %s\n", "image.ppm");
    free(img);
    fputs("Done.\n", stderr);
    return 0;
}

